# backend/logic.py - Python 3.11
# Compute: sum item.price * item.qty for each item in payload.items; empty items means zero.
# Input payload is a Python dict; return exactly a dict with key 'value'.
# value type: number.
def transform(payload):
    return {
        'value': sum(item.price * item.qty for item in payload.items if item.qty > 0)
    }

Fullstack/00.api:
const express = require('express');
// server/index.js: POST /api/invoice accepts JSON payload and responds
// HTTP 200 with JSON {data: processor(req.body)}.
// processor is a supplied synchronous Python-logic bridge.
// Create an Express app with express.json(), register the POST route, return app.
function createApp(processor) {
  const app = express();
  app.use(express.json());
  app.post('/api/invoice', (req, res) => {
    const data = req.body;
    const result = processor(data);
    res.json({ data: result });
  });
  return app;
}

module.exports = createApp;

